from pathlib import Path
import subprocess
P=Path(__file__).resolve().parent/'diagrams';P.mkdir(exist_ok=True)
BASE='''digraph G { graph [rankdir=TB,bgcolor="transparent",pad=.2,nodesep=.28,ranksep=.5]; node [shape=box,style="rounded,filled",fillcolor="#eaf5f2",color="#61a99c",fontname="DejaVu Sans",fontsize=10,margin=".14,.1"]; edge [color="#567181",fontname="DejaVu Sans",fontsize=8,arrowsize=.65];\n'''
graphs={
'01_use_cases':'''driver [label="Driver / request operator",fillcolor="#dbeafa"]; admin [label="Facility operator",fillcolor="#dbeafa"]; examiner [label="Examiner",fillcolor="#dbeafa"];
request [label="Submit request",shape=ellipse]; options [label="Inspect eligible options",shape=ellipse]; confirm [label="Confirm reservation",shape=ellipse]; cancel [label="Cancel booking",shape=ellipse]; move [label="Move reservation safely",shape=ellipse]; status [label="Change sensor / closure",shape=ellipse]; clock [label="Advance simulation clock",shape=ellipse]; proof [label="Inspect facts and proofs",shape=ellipse]; export [label="Export evidence",shape=ellipse];
driver -> request;driver -> options;driver -> confirm;driver -> cancel;admin -> status;admin -> move;admin -> clock;examiner -> proof;examiner -> export;options -> proof [label="explained by"];move -> options [label="rechecks"];''',
'02_context':'''user [label="Operator\nrequest + selected action"];sim [label="ParkWise simulator\npolicy + reasoning + booking state",fillcolor="#ccebdd"];ui [label="Decision output\nrecommended bay + alternatives"];evidence [label="Evidence export\nJSON snapshot + proofs"];sensor [label="Synthetic facility state\nsensors / chargers / maintenance"];user -> sim;sensor -> sim;sim -> ui;sim -> evidence;''',
'03_architecture':'''ui [label="Presentation layer\nHTML / CSS / DOM events",fillcolor="#dbeafa"];actions [label="Application actions\nconfirm / cancel / reallocate / clock"];adapter [label="Fact adapter\nvalidation + interval / cost checks"];policy [label="policy.json\n34 shared rule schemas"];ground [label="Finite grounder\nrequest, bay and booking bindings"];fwd [label="Indexed forward engine\nclosure + firing trace"];bwd [label="Head-indexed backward engine\ngoal proof tree"];select [label="Agreement check + ranking\ndistance, cost, bay ID"];state [label="Session state\nrequests / bays / bookings",shape=cylinder];ui -> actions;actions -> adapter;actions -> state [label="atomic mutations"];state -> adapter;policy -> ground;adapter -> ground;ground -> fwd;ground -> bwd;fwd -> select;bwd -> select;select -> ui [label="explanations",constraint=false];''',
 '04_frames':'''bay [label="Bay\\nopen=true, rate=100"];g [label="GeneralBay"];a [label="AccessibleBay"];e [label="ChargingBay"];m [label="MotorcycleBay"];
bay -> g [label="parent of"];bay -> a;bay -> e;bay -> m;
req [label="Request\\nverified=false, budget=500"];book [label="Booking\\nadds bay reference"];veh [label="Vehicle"];ev [label="ElectricVehicle"];bike [label="Motorcycle"];
g -> req [style=invis];m -> veh [style=invis];req -> book [label="parent of"];veh -> ev [label="parent of"];veh -> bike;
''',
'05_semantic_network':'''facility [label="Facility"];zone [label="Zone"];bay [label="Bay"];charger [label="Charger"];sensor [label="Sensor"];request [label="Request"];vehicle [label="Vehicle"];booking [label="Booking"];interval [label="Time interval"];proof [label="Proof"];facility -> zone [label="contains"];zone -> bay [label="contains"];bay -> sensor [label="observedBy"];bay -> charger [label="hasEquipment (optional)"];booking -> request [label="IS-A"];booking -> bay [label="assignedTo"];request -> vehicle [label="usesVehicle"];request -> interval [label="requestsInterval"];proof -> request [label="explains"];request -> bay [label="candidateFor (derived)"];''',
'06_erd':'''node [shape=record,style=filled]; facility [label="{Facility|name|opens / closes}"];zone [label="{Zone|name|level}"];bay [label="{Bay|id (PK)|kind / zone / rate|height / width / max_minutes|open / sensor / charger}"];req [label="{Request|id (session key)|vehicle / dimensions|start / end / budget|verified / enabled / badge / charge}"];booking [label="{Booking|id (unique)|bay (FK)|request snapshot}"];policy [label="{RuleSchema|id (PK)|scope / head / body}"];evidence [label="{Evidence|snapshot|facts / closure / proofs}"];
facility -> zone [label="1 to many"];zone -> bay [label="1 to many"];req -> booking [label="0..1 confirmation"];bay -> booking [label="1 to many over time"];req -> evidence [label="1 to many evaluations"];policy -> evidence [label="grounds into"];''',
'07_dataflow':'''input [label="Input request + facility snapshot"];validate [label="Validate types, IDs and invariants"];facts [label="Compute explicit base facts\nclearance / cost / occupancy"];ground [label="Instantiate policy schemas"];reason [label="Run both inference engines"];rank [label="Rank proved candidates"];result [label="Decision + alternatives + proofs"];input -> validate;validate -> facts;facts -> ground;ground -> reason;reason -> rank;rank -> result;''',
'08_activity':'''start [label="Request submitted",shape=oval];valid [label="Input valid?",shape=diamond];err [label="Show input error",fillcolor="#fbe7e4"];derive [label="Build facts and run both engines"];agree [label="Results agree?",shape=diamond];stop [label="Stop on engine discrepancy",fillcolor="#fbe7e4"];exists [label="Any candidate?",shape=diamond];deny [label="Explain failed conditions",fillcolor="#fff1d7"];rank [label="Sort by distance, cost, ID"];confirm [label="User confirms?",shape=diamond];save [label="Re-evaluate latest state\nthen save one booking"];show [label="Display options and proof"];start -> valid;valid -> err [label="no"];valid -> derive [label="yes"];derive -> agree;agree -> stop [label="no"];agree -> exists [label="yes"];exists -> deny [label="no"];exists -> rank [label="yes"];rank -> show;show -> confirm;confirm -> save [label="yes"];''',
'09_lifecycle':'''draft [label="Unconfirmed request",shape=oval];pending [label="Pending reservation\nclock < start"];active [label="Active interval\nstart <= clock < end"];done [label="Completed interval\nclock >= end"];cancelled [label="Cancelled / removed",shape=oval,fillcolor="#fbe7e4"];draft -> pending [label="confirm future interval"];draft -> active [label="confirm current interval"];pending -> active [label="clock reaches start"];active -> done [label="clock reaches end"];pending -> cancelled [label="cancel"];active -> cancelled [label="cancel"];done -> cancelled [label="clear record"];pending -> pending [label="atomic move changes bay"];active -> active [label="atomic move changes bay"];''',
'10_reallocation':'''original [label="1. Original booking remains in live state",fillcolor="#dbeafa"];copy [label="2. Create trial copy; remove original only in trial"];eval [label="3. Evaluate original request against trial"];find [label="4. Alternative bay exists?",shape=diamond];retain [label="5a. Reject move\noriginal unchanged",fillcolor="#fbe7e4"];replace [label="5b. Replace original in one live-state update",fillcolor="#d9f3e5"];result [label="6. Log old bay -> new bay"];original -> copy;copy -> eval;eval -> find;find -> retain [label="no"];find -> replace [label="yes"];replace -> result;''',
'11_forward_dependencies':'''candidate [label="candidate(R1,G1)\nH16",fillcolor="#ccebdd"];ad [label="admissible(R1)\nH15"];co [label="compatible(R1,G1)\nH13"];av [label="available(R1,G1)\nH14"];cm [label="commercial_fit(R1,G1)\nH12"];au [label="authorized + schedulable\nH01 / H02"];fit [label="size + access + service + dimensions\nH03,H05,H07,H09,H11"];free [label="bay + operational\nsensor_free + booking_clear"];cost [label="budget_ok + duration_ok"];au -> ad;fit -> co;free -> av;cost -> cm;ad -> candidate;co -> candidate;av -> candidate;cm -> candidate;''',
'12_backward_proof':'''c [label="Goal: candidate(R1,G1)\nPROVED by H16",fillcolor="#ccebdd"];a [label="admissible(R1)\nH15"];x [label="compatible(R1,G1)\nH13"];v [label="available(R1,G1)\nH14"];m [label="commercial_fit(R1,G1)\nH12"];a1 [label="authorized\nH01"];a2 [label="schedulable\nH02"];a3 [label="verified, account_enabled\nBASE FACTS"];a4 [label="request, valid_window, inside_hours\nBASE FACTS"];x1 [label="size_fit, access_fit\nservice_fit, dimension_fit"];v1 [label="bay, operational\nsensor_free, booking_clear\nBASE FACTS"];m1 [label="budget_ok, duration_ok\nBASE FACTS"];c -> a;c -> x;c -> v;c -> m;a -> a1;a -> a2;a1 -> a3;a2 -> a4;x -> x1;v -> v1;m -> m1;''',
'13_failed_proof':'''c [label="candidate(R1,G1)\nNOT PROVED",fillcolor="#fbe7e4"];av [label="available(R1,G1)\nH14 cannot complete"];sf [label="sensor_free(G1)\nMISSING",fillcolor="#fbe7e4"];u [label="sensor_unknown(G1)\nEXPLICIT FACT",fillcolor="#fff1d7"];rev [label="manual_review(R1,G1)\nPROVED by H20",fillcolor="#fff1d7"];c -> av;av -> sf;u -> rev;sf -> u [style=dashed,label="different known state",dir=none];''',
'14_taxonomy':'''bay [label="Bay"];g [label="GeneralBay"];a [label="AccessibleBay"];e [label="ChargingBay"];m [label="MotorcycleBay"];v [label="Vehicle"];ev [label="ElectricVehicle"];car [label="Car"];bike [label="Motorcycle"];g -> bay [label="subClassOf"];a -> bay;e -> bay;m -> bay;ev -> v;car -> v;bike -> v;g -> e [dir=none,style=dashed,color="#c5766e",label="disjoint"];car -> bike [dir=none,style=dashed,color="#c5766e",label="disjoint"];'''
}
for name,body in graphs.items():
 (P/(name+'.dot')).write_text(BASE+body+'\n}')
 subprocess.run(['dot','-Tpng','-Gdpi=160',str(P/(name+'.dot')),'-o',str(P/(name+'.png'))],check=True)
print('Rendered',len(graphs),'diagrams')
